def run_group_chat(agents, task, is_termination, max_round):
    transcript = [task]
    for rnd in range(max_round):
        # round-robin speaker selection
        speaker = agents[rnd % len(agents)]
        content = speaker["respond"](transcript[-1])
        transcript.append(content)
        if is_termination(content):
            return transcript, "keyword"   # stopped early by a termination message
    return transcript, "max_round"          # hard cap fired first

